package vn.smartprop.storage;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.security.MessageDigest;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import vn.smartprop.common.*;
@Service
public class StorageLifecycle {
    private final JdbcTemplate jdbc;private final Path root;private final ObjectMapper json;
    public record Entry(String key,String state,long bytes,String sha256) {}
    public record Receipt(String id,String key,String sha256,Instant quarantinedAt) {}
    public StorageLifecycle(JdbcTemplate jdbc,ObjectMapper json,@Value("${app.storage-root:./var/uploads}") String root){this.jdbc=jdbc;this.json=json;this.root=Path.of(root).toAbsolutePath().normalize();}
    private boolean table(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name=?",Integer.class,table)>0;}
    public Set<String> references(){String sql="SELECT storage_key FROM property_images UNION SELECT storage_key FROM report_attachments";if(table("property_legal_documents"))sql+=" UNION SELECT storage_key FROM property_legal_documents";return new HashSet<>(jdbc.query(sql,(r,n)->r.getString(1)));}
    private String hash(Path p)throws Exception{try(var in=Files.newInputStream(p,LinkOption.NOFOLLOW_LINKS)){var digest=MessageDigest.getInstance("SHA-256");byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)digest.update(bytes,0,n);return HexFormat.of().formatHex(digest.digest());}}
    private Path file(String key)throws Exception{if(key==null||!key.matches("[a-f0-9]{32}\\.bin"))throw ApiInputs.bad("Invalid storage key");if(Files.isSymbolicLink(root)||!root.toRealPath().equals(root.toRealPath(LinkOption.NOFOLLOW_LINKS)))throw ApiInputs.bad("Storage root must be canonical, without links");var p=root.resolve(key);if(!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS)||Files.isSymbolicLink(p))throw ApiInputs.missing();return p;}
    public List<Entry> scan(int graceDays)throws Exception{if(graceDays<7)throw ApiInputs.bad("Minimum grace is 7 days");Set<String> refs=references();List<Entry> result=new ArrayList<>();for(String key:refs)if(key!=null&&key.matches("[a-f0-9]{32}\\.bin")&&!Files.isRegularFile(root.resolve(key),LinkOption.NOFOLLOW_LINKS))result.add(new Entry(key,"MISSING_REFERENCED",0,null));if(!Files.exists(root))return result;if(Files.isSymbolicLink(root)||!root.toRealPath().equals(root.toRealPath(LinkOption.NOFOLLOW_LINKS)))throw ApiInputs.bad("Noncanonical storage root");
        try(var paths=Files.list(root)){for(var p:paths.toList()){String key=p.getFileName().toString();if(!key.matches("[a-f0-9]{32}\\.bin")||!Files.isRegularFile(p,LinkOption.NOFOLLOW_LINKS))continue;boolean old=Files.getLastModifiedTime(p,LinkOption.NOFOLLOW_LINKS).toInstant().isBefore(Instant.now().minus(Duration.ofDays(graceDays)));result.add(new Entry(key,refs.contains(key)?"REFERENCED":old?"QUARANTINE_CANDIDATE":"RECENT_KEEP",Files.size(p),old&&!refs.contains(key)?hash(p):null));}}return List.copyOf(result);}
    public Receipt quarantine(String key,String expectedHash,Path backup,boolean writersPaused)throws Exception{if(!writersPaused)throw ApiInputs.conflict("Pause all storage writers before quarantine");Path source=file(key);if(references().contains(key)||!Files.getLastModifiedTime(source).toInstant().isBefore(Instant.now().minus(Duration.ofDays(7))))throw ApiInputs.conflict("Referenced or recent file");String actual=hash(source);if(!Objects.equals(expectedHash,actual))throw ApiInputs.conflict("File changed");backup=backup.toRealPath();var manifest=json.readTree(Files.readAllBytes(backup.resolve("manifest.json")));if(!manifest.path("complete").asBoolean(false))throw ApiInputs.conflict("Complete backup required");boolean covered=false;for(var entry:manifest.path("files")){String name=entry.path("file").asText().replace('\\','/');if(name.equals("uploads/"+key)&&actual.equalsIgnoreCase(entry.path("sha256").asText()))covered=true;}Path copy=backup.resolve("uploads").resolve(key);if(!covered||!Files.isRegularFile(copy,LinkOption.NOFOLLOW_LINKS)||!actual.equals(hash(copy)))throw ApiInputs.conflict("Verified backup copy required");
        Path directory=root.resolve(".quarantine");Files.createDirectories(directory);if(Files.isSymbolicLink(directory)||!directory.toRealPath().equals(directory.toRealPath(LinkOption.NOFOLLOW_LINKS)))throw ApiInputs.bad("Invalid quarantine path");String id=UUID.randomUUID().toString();Path destination=directory.resolve(id+".bin"),receiptPath=directory.resolve(id+".json");Receipt receipt=new Receipt(id,key,actual,Instant.now());Files.write(receiptPath,json.writeValueAsBytes(receipt),StandardOpenOption.CREATE_NEW);if(references().contains(key))throw ApiInputs.conflict("File became referenced");Files.move(source,destination);return receipt;
    }
    public void restore(String id)throws Exception{id=ApiInputs.uuid(id);Path dir=root.resolve(".quarantine");if(Files.isSymbolicLink(root)||Files.isSymbolicLink(dir)||!dir.toRealPath().equals(dir.toRealPath(LinkOption.NOFOLLOW_LINKS)))throw ApiInputs.bad("Invalid quarantine path");if(Files.isSymbolicLink(dir.resolve(id+".json")))throw ApiInputs.bad("Invalid receipt path");var receipt=json.readValue(Files.readAllBytes(dir.resolve(id+".json")),Receipt.class);if(!id.equals(receipt.id())||!receipt.key().matches("[a-f0-9]{32}\\.bin"))throw ApiInputs.bad("Invalid receipt");Path source=dir.resolve(id+".bin"),destination=root.resolve(receipt.key());if(Files.exists(destination,LinkOption.NOFOLLOW_LINKS)||Files.isSymbolicLink(source)||!receipt.sha256().equals(hash(source)))throw ApiInputs.conflict("Restore target exists or bytes changed");Files.move(source,destination);}
}
